Component Arduino Pin Description LM35 VCC 5V Power supply to the sensor LM35 GND GND Common ground LM35 Output A0 Analog output signal to Arduino <pre><code>int sensorPin = A0;    // Analog pin A0 connected to LM35 temperature sensor
float sensorValue;     // Variable for storing the raw sensor reading (0–1023)
float temperatureC;    // Variable for storing the calculated temperature in Celsius

void setup() {
  Serial.begin(9600);  // Start serial communication at 9600 bits per second
}

void loop() {
  sensorValue = analogRead(sensorPin);  // Read the analog value from LM35 (0 to 1023)

  // Convert the analog reading to temperature in °C:
  // (analog value * 5V * 100) / 1024 levels = temperature in Celsius
  temperatureC = (sensorValue * 5.0 * 100.0) / 1024.0;

  Serial.print("Temperature: ");  // Print the label "Temperature: " to the Serial Monitor
  Serial.print(temperatureC);     // Print the temperature value
  Serial.println(" °C");          // Print the °C symbol and move to the next line

  delay(1000); // Wait 1 second before reading again
}
